recall.code:
use std::marker::PhantomData;
struct Ready; struct Running;
struct Job<S> { id: u32, state: PhantomData<S> }
impl Job<Ready> {
    fn start(self) -> Job<Running> { Job { id: self.id, state: PhantomData } }
}
impl Job<Running> { fn finish(self) {} }

let job = Job::<Ready> { id: 1, state: PhantomData };
job.finish();
